- (void)layoutSubviews{[super layoutSubviews];CGFloat left=MAX(12,self.safeAreaInsets.left),right=MAX(12,self.safeAreaInsets.right);CGFloat width=MAX(0,self.bounds.size.width-left-right);self.control.frame=CGRectMake(left,6,width,34);NSUInteger count=self.control.numberOfSegments;for(NSUInteger i=0;i<count;i++)[self.control setWidth:count?width/count:0 forSegmentAtIndex:i];CGFloat fontSize=width<310?12:13;[self.control setTitleTextAttributes:@{NSFontAttributeName:[UIFont systemFontOfSize:fontSize weight:UIFontWeightMedium]} forState:UIControlStateNormal];}
