@interface TFAISessionFiles : UITableViewController <UISearchResultsUpdating,UIDocumentInteractionControllerDelegate>
@property NSDictionary *session;
@property NSString *projectRoot;
@property NSString *directory;
@property NSDictionary *directoryGrant;
