@property BOOL scopedAccess;
@property NSString *boundary;
@property NSArray *items;
@property NSArray *filtered;
@property UIDocumentInteractionController *document;
@property(copy) void (^locateMessage)(NSString *messageID);
@property NSString *category;
@property NSString *sourceMessageID;
@property UISegmentedControl *categories;
