@end
@implementation TFAISessionFiles
- (void)viewDidLoad{[super viewDidLoad];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(remoteSessionChanged:) name:@"TFAISessionRemoteDidChange" object:nil];self.title=self.directory?TFAIAttachmentFolderName(self.directory):DXLoc(@"会话文件");self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=62;UISearchController *search=[[UISearchController alloc]initWithSearchResultsController:nil];search.obscuresBackgroundDuringPresentation=NO;search.searchBar.placeholder=self.directory?@"搜索当前文件夹":DXLoc(@"搜索名称、来源或类型");search.searchResultsUpdater=self;self.navigationItem.searchController=search;self.navigationItem.rightBarButtonItem=AIBar(@"arrow.clockwise",DXLoc(@"刷新文件"),self,@selector(refresh));if(!self.directory){self.categories=[[UISegmentedControl alloc]initWithItems:@[@"全部",DXLoc(@"附件"),DXLoc(@"生成"),DXLoc(@"头文件"),DXLoc(@"构建"),DXLoc(@"项目")]];self.categories.selectedSegmentIndex=0;[self.categories addTarget:self action:@selector(categoryChanged) forControlEvents:UIControlEventValueChanged];TFAISessionCategoryHeader *header=[[TFAISessionCategoryHeader alloc]initWithFrame:CGRectMake(0,0,self.tableView.bounds.size.width,46)];header.control=self.categories;self.categories.apportionsSegmentWidthsByContent=NO;[header addSubview:self.categories];self.tableView.tableHeaderView=header;}if(self.directoryGrant)self.navigationItem.rightBarButtonItems=@[self.navigationItem.rightBarButtonItem,AIBar(@"folder.badge.minus",DXLoc(@"管理目录授权"),self,@selector(manageDirectoryGrant))];[self refresh];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self refresh];}
- (void)remoteSessionChanged:(NSNotification *)note{if([note.userInfo[@"sessionID"] isEqual:self.session[@"id"]]&&[note.userInfo[@"projectID"] isEqual:self.session[@"storageProjectID"]])[self refresh];}
- (void)dealloc{[NSNotificationCenter.defaultCenter removeObserver:self];if(self.scopedAccess)[self.scopedURL stopAccessingSecurityScopedResource];}
- (void)manageDirectoryGrant{[self.navigationController pushViewController:TFAISentAttachmentPreview(self.directoryGrant) animated:YES];}
- (void)refresh{if(self.directoryGrant){NSError *error=nil;if(!TFAIReadDirectoryReference(self.directoryGrant,@{@"action":@"validate"},&error)){self.items=@[];[self updateSearchResultsForSearchController:self.navigationItem.searchController];AIAlert(self,DXLoc(@"目录不可访问"),error.localizedDescription);return;}}NSDictionary *snapshot=self.session;NSString *directory=self.directory,*project=self.projectRoot,*boundary=self.boundary;NSUInteger generation=++self.refreshGeneration;self.navigationItem.rightBarButtonItem.enabled=NO;__weak typeof(self) weak=self;
 dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSDictionary *latest=[snapshot[@"id"] length]?[TFAISessions loadSession:snapshot[@"id"] project:snapshot[@"storageProjectID"]?:@"general"]:nil;
 NSDictionary *current=[latest[@"remoteRevision"] unsignedLongLongValue]>[snapshot[@"remoteRevision"] unsignedLongLongValue]?latest:snapshot;
 NSArray *items=TFAISessionResourceIndex(current,project,directory,boundary,self.sourceMessageID);
 dispatch_async(dispatch_get_main_queue(),^{if(!weak||weak.refreshGeneration!=generation)return;weak.items=items;weak.navigationItem.rightBarButtonItem.enabled=YES;[weak updateSearchResultsForSearchController:weak.navigationItem.searchController];});});}
- (void)categoryChanged{NSArray *values=@[@"",DXLoc(@"附件"),DXLoc(@"生成"),DXLoc(@"头文件"),DXLoc(@"构建"),DXLoc(@"项目")];self.category=values[self.categories.selectedSegmentIndex];[self updateSearchResultsForSearchController:self.navigationItem.searchController];}
- (void)updateSearchResultsForSearchController:(UISearchController *)search{NSString *query=search.searchBar.text?:@"";self.filtered=[self.items filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *item,NSDictionary *bindings){BOOL category=!self.category.length||[item[@"source"] isEqual:self.category];NSString *text=[NSString stringWithFormat:@"%@ %@ %@",item[@"name"]?:@"",item[@"category"]?:@"",item[@"source"]?:@""];return category&&(!query.length||[text localizedCaseInsensitiveContainsString:query]);}]];UILabel *empty=[UILabel new];empty.text=DXLoc(@"暂无匹配的会话文件");empty.textAlignment=NSTextAlignmentCenter;empty.textColor=UIColor.secondaryLabelColor;self.tableView.backgroundView=self.filtered.count?nil:empty;[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return self.filtered.count;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)index{NSDictionary *item=self.filtered[index.row];NSString *path=item[@"localPath"];NSString *kind=item[@"category"]?:DXLoc(@"文件");NSString *size=[item[@"folder"] boolValue]?@"文件夹":[NSByteCountFormatter stringFromByteCount:[item[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile];NSString *detail=path.length?[NSString stringWithFormat:@"%@ · %@",kind,size]:kind;if([item[@"modified"] doubleValue]>0){NSDateFormatter *format=[NSDateFormatter new];format.dateFormat=@"yyyy-MM-dd HH:mm:ss";detail=[detail stringByAppendingFormat:@"\n%@ %@",item[@"timeLabel"]?:DXLoc(@"修改于"),[format stringFromDate:[NSDate dateWithTimeIntervalSince1970:[item[@"modified"] doubleValue]]]];}UITableViewCell *cell=AICell(item[@"name"],detail,([item[@"folder"] boolValue]||item[@"previewItem"][@"directoryGrant"])?@"folder":@"doc");cell.textLabel.numberOfLines=2;cell.detailTextLabel.numberOfLines=2;cell.detailTextLabel.font=[UIFont systemFontOfSize:12];cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}
- (NSString *)tableView:(UITableView *)table titleForFooterInSection:(NSInteger)section{return DXLoc(@"仅在本机浏览，不会自动发送给模型。文件保留在原目录；已移除的文件需重新导入。");}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)index{[table deselectRowAtIndexPath:index animated:YES];NSDictionary *item=self.filtered[index.row];if(self.directoryGrant){NSError *error=nil;if(!TFAIReadDirectoryReference(self.directoryGrant,@{@"action":@"validate"},&error)){AIAlert(self,DXLoc(@"目录不可访问"),error.localizedDescription);return;}}NSDictionary *grant=item[@"previewItem"][@"directoryGrant"]?item[@"previewItem"]:nil;if(grant){NSError *error=nil;NSURL *url=TFAIDirectoryBrowserURL(grant,&error);if(!url){AIAlert(self,DXLoc(@"目录不可访问"),error.localizedDescription);return;}TFAISessionFiles *child=[[TFAISessionFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];child.directory=url.path;child.boundary=url.path;child.directoryGrant=grant;child.scopedURL=url;child.scopedAccess=[url startAccessingSecurityScopedResource];child.locateMessage=self.locateMessage;child.sourceMessageID=item[@"messageID"];[self.navigationController pushViewController:child animated:YES];return;}NSString *path=item[@"localPath"];if(path.length&&!SFInside(item[@"accessBoundary"],path)){AIAlert(self,DXLoc(@"文件已变化"),DXLoc(@"请重新导入或生成文件。"));return;}if([item[@"folder"] boolValue]){TFAISessionFiles *child=[[TFAISessionFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];child.directory=path;child.directoryGrant=self.directoryGrant;child.boundary=self.boundary?:path;child.locateMessage=self.locateMessage;child.sourceMessageID=item[@"messageID"]?:self.sourceMessageID;[self.navigationController pushViewController:child animated:YES];return;}if(item[@"previewItem"]&&!path.length){[self.navigationController pushViewController:TFAISentAttachmentPreview(item[@"previewItem"]) animated:YES];return;}NSDictionary *attrs=[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil];if(![attrs[NSFileType] isEqual:NSFileTypeRegular]){AIAlert(self,DXLoc(@"文件已移除"),DXLoc(@"请重新生成或导入。"));return;}if([attrs[NSFileSize] unsignedLongLongValue]<=2*1024*1024){NSString *text=[NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];if(text){[self.navigationController pushViewController:TFAISentAttachmentPreview(@{@"path":item[@"name"],@"preview":text}) animated:YES];return;}}
 self.document=[UIDocumentInteractionController interactionControllerWithURL:[NSURL fileURLWithPath:path]];self.document.delegate=self;if(![self.document presentPreviewAnimated:YES]){UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[[NSURL fileURLWithPath:path]] applicationActivities:nil];share.popoverPresentationController.sourceView=self.view;share.popoverPresentationController.sourceRect=CGRectMake(self.view.bounds.size.width/2,self.view.bounds.size.height/2,1,1);[self presentViewController:share animated:YES completion:nil];}}
- (UIContextMenuConfiguration *)tableView:(UITableView *)table contextMenuConfigurationForRowAtIndexPath:(NSIndexPath *)index point:(CGPoint)point{
 NSDictionary *item=self.filtered[index.row];__weak typeof(self) weak=self;return [UIContextMenuConfiguration configurationWithIdentifier:nil previewProvider:nil actionProvider:^UIMenu *(NSArray *suggested){NSMutableArray *actions=[NSMutableArray new];NSString *path=item[@"localPath"],*message=item[@"messageID"];if(path.length&&![item[@"folder"] boolValue])[actions addObject:[UIAction actionWithTitle:DXLoc(@"分享文件") image:[UIImage systemImageNamed:@"square.and.arrow.up"] identifier:nil handler:^(UIAction *a){BOOL folder=NO;if(!SFInside(item[@"accessBoundary"],path)||![NSFileManager.defaultManager fileExistsAtPath:path isDirectory:&folder]||folder)return;UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[[NSURL fileURLWithPath:path]] applicationActivities:nil];share.popoverPresentationController.sourceView=weak.view;share.popoverPresentationController.sourceRect=CGRectMake(weak.view.bounds.size.width/2,weak.view.bounds.size.height/2,1,1);[weak presentViewController:share animated:YES completion:nil];}]];if(message.length&&weak.locateMessage)[actions addObject:[UIAction actionWithTitle:DXLoc(@"定位到消息") image:[UIImage systemImageNamed:@"bubble.left"] identifier:nil handler:^(UIAction *a){weak.locateMessage(message);}]];return [UIMenu menuWithTitle:@"" children:actions];}];
}
- (UIViewController *)documentInteractionControllerViewControllerForPreview:(UIDocumentInteractionController *)controller{return self;}
@end
UIViewController *TFAISessionFilesController(NSDictionary *session,NSString *projectRoot){TFAISessionFiles *view=[[TFAISessionFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];view.session=session;view.projectRoot=projectRoot;return view;}

UIViewController *TFAISessionFilesControllerWithNavigation(NSDictionary *session,NSString *projectRoot,void (^locateMessage)(NSString *messageID)){TFAISessionFiles *view=(id)TFAISessionFilesController(session,projectRoot);view.locateMessage=locateMessage;return view;}
